sys_hub_input_scripts.script:
{"retry_flag":{"scriptActive":true,"script":"if (fd_data._10__wait_until_tracker_completes.status != 3)
 return false;

if (fd_data._10__wait_until_tracker_completes.status_detail != 'App Repository busy, please try again later')
 return false;

var attempt = fd_data.flow_var.attempt;
var max = fd_data.flow_var.max_attempts;

if (parseInt(attempt) >= parseInt(max))
 return false;

return true;"}}

